import unittest

class Test(unittest.TestCase):
    def test_closed_calls_through(self):
        cb = CircuitBreaker(3, 10.0)
        self.assertEqual(cb.call(lambda: 'ok', now=0.0), 'ok')
    def test_opens_after_threshold_failures(self):
        cb = CircuitBreaker(2, 10.0)
        def fail(): raise ValueError('x')
        for t in [0.0, 1.0]:
            with self.assertRaises(ValueError):
                cb.call(fail, now=t)
        with self.assertRaises(RuntimeError):
            cb.call(lambda: 'ok', now=2.0)
    def test_half_open_after_timeout_succeeds_closes(self):
        cb = CircuitBreaker(1, 5.0)
        def fail(): raise ValueError('x')
        with self.assertRaises(ValueError):
            cb.call(fail, now=0.0)
        with self.assertRaises(RuntimeError):
            cb.call(lambda: 'ok', now=1.0)
        self.assertEqual(cb.call(lambda: 'recovered', now=6.0), 'recovered')
        self.assertEqual(cb.call(lambda: 'ok2', now=7.0), 'ok2')

if __name__ == '__main__':
    unittest.main()
